package lk.ac.sliit.ridelink.ride.presentation.controller;
import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.tags.Tag; import lk.ac.sliit.ridelink.ride.application.dto.response.RideResponse; import lk.ac.sliit.ridelink.ride.application.port.in.RideLifecycleUseCase; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.UUID;
@RestController @RequestMapping("/api/v1/internal/rides") @Tag(name="Internal ride recovery") @SecurityRequirement(name="bearerAuth") public class InternalRideController {private final RideLifecycleUseCase rides;public InternalRideController(RideLifecycleUseCase rides){this.rides=rides;}@PostMapping("/{rideId}/driver-sync") @PreAuthorize("hasAnyRole('SERVICE','ADMIN')") public RideResponse retry(@PathVariable UUID rideId){return rides.retryDriverRelease(rideId);}}
